// A victory can enter "settled" while the final settlement effect is still on screen.
function readyForTacticalAftermath(state) {
  return state.phase === "settled" && state.terminal === "victory" &&
    state.pendingEffects.length === 0 && state.tasks.length === 0;
}

const pendingLateSaveNotices = new WeakMap();
function lateSaveStatusPending(status) {
  const token = pendingLateSaveNotices.get(status);
  if (!token) return false;
  if (token.isCurrent()) return true;
  pendingLateSaveNotices.delete(status);
  return false;
}
function beginLateSaveNotice(stage, isCurrent) {
  const pending = "正在儲存並核對中斷記錄，完成前請保留本頁。";
  stage.textContent = pending;
  const status = stage.closest?.("#battle-view")?.querySelector("#game-save-status");
  if (!status) return;
  const earlier = pendingLateSaveNotices.get(status);
  const previous = earlier && status.textContent === pending ? earlier.previous : status.textContent;
  const token = {isCurrent, previous};
  pendingLateSaveNotices.set(status, token);
  status.textContent = pending;
  return result => {
    if (pendingLateSaveNotices.get(status) !== token) return;
    pendingLateSaveNotices.delete(status);
    if (status.textContent !== pending) return;
    if (result === true) status.textContent = "中斷記錄已儲存。";
    else if (result === false) status.textContent = "未能確認今次儲存結果，請核對中斷記錄。";
    else status.textContent = previous;
  };
}
